WITH base AS (SELECT id, name, email, country, city, signup_date, is_active, credit_limit, age, TRIM(country) AS clean_country FROM customers WHERE UPPER(TRIM(email)) = 'GRACE.KIM@GMAIL.COM'), with_windows AS (SELECT *, AVG(age) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS age_avg_6, LAG(age, 2, 0) OVER (PARTITION BY country ORDER BY signup_date, id) AS prev_age FROM base WHERE name LIKE 'b%'), kept AS (SELECT s.* FROM with_windows s WHERE NOT EXISTS (SELECT 1 FROM sessions x WHERE x.customer_id = s.id AND x.started_at < s.signup_date)), enriched AS (SELECT id, country, city, credit_limit, age, prev_age, LAST_VALUE(city) IGNORE NULLS OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city, SUM(credit_limit) OVER (PARTITION BY city ORDER BY prev_age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, NTILE(4) OVER (PARTITION BY country ORDER BY age_avg_6, id) AS age_avg_6_bucket FROM kept), summary AS (SELECT CASE WHEN age_avg_6_bucket >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_avg_6_bucket_tier, CASE WHEN cumulative_credit_limit >= 84977 THEN 'HIGH' ELSE 'LOW' END AS cumulative_credit_limit_tier, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS age_per_us, SUM(CASE WHEN city = 'New York' THEN cumulative_credit_limit ELSE 0 END) AS new_york_cumulative_credit_limit, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN country = 'UK' THEN 1 END), 0), 2) AS age_per_uk, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, COUNT(*) AS event_count, MAX(credit_limit) FILTER (WHERE city = 'Berlin') AS berlin_max_credit_limit FROM enriched GROUP BY CASE WHEN age_avg_6_bucket >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN cumulative_credit_limit >= 84977 THEN 'HIGH' ELSE 'LOW' END) SELECT age_avg_6_bucket_tier, cumulative_credit_limit_tier, age_per_us, new_york_cumulative_credit_limit, age_per_uk, credit_limit_stddev, event_count, berlin_max_credit_limit FROM summary
